   125 │ func (c *Client) sign(method, path, ts, nonce string, body []byte) string {
   126 │ 	bodyHash := sha256.Sum256(body)
   127 │ 	msg := fmt.Sprintf("%s\n%s\n%s\n%s\n%s", method, path, ts, nonce, hex.EncodeToString(bodyHash[:]))
