   136 │ 	var err error
   137 │ 	if payload != nil {
   138 │ 		body, err = json.Marshal(payload)
   139 │ 		if err != nil {
   140 │ 			return nil, err
   141 │ 		}
   142 │ 	}
   143 │ 	ts := fmt.Sprintf("%d", time.Now().Unix())
   144 │ 	nonceBytes := make([]byte, 16)
   145 │ 	if _, err := rand.Read(nonceBytes); err != nil {
   146 │ 		return nil, err
   147 │ 	}
   148 │ 	nonce := hex.EncodeToString(nonceBytes)
   149 │ 
   150 │ 	req, err := http.NewRequest(method, c.ServerURL+path, bytes.NewReader(body))
   151 │ 	if err != nil {
   152 │ 		return nil, err
   153 │ 	}
   154 │ 	req.Header.Set("Content-Type", "application/json")
   155 │ 	req.Header.Set("X-Token", c.Token)
   156 │ 	req.Header.Set("X-Timestamp", ts)
   157 │ 	req.Header.Set("X-Nonce", nonce)
   158 │ 	req.Header.Set("X-Sign", c.sign(method, path, ts, nonce, body))
   159 │ 	return req, nil
