   170 │ 	data, _ := io.ReadAll(resp.Body)
   171 │ 	if resp.StatusCode != http.StatusOK {
   172 │ 		var e struct {
   173 │ 			Error string `json:"error"`
   174 │ 		}
   175 │ 		_ = json.Unmarshal(data, &e)
   176 │ 		msg := e.Error
   177 │ 		if msg == "" {
   178 │ 			msg = string(data)
   179 │ 		}
   180 │ 		switch resp.StatusCode {
   181 │ 		case http.StatusForbidden:
   182 │ 			return errors.New(msg) // 激活码失效/设备数上限
   183 │ 		case http.StatusUnauthorized:
   184 │ 			return errors.New("授权校验失败: " + msg)
   185 │ 		case http.StatusTooManyRequests:
   186 │ 			return errors.New(msg)
   187 │ 		case http.StatusBadGateway:
   188 │ 			return errors.New(msg)
   189 │ 		default:
   190 │ 			return fmt.Errorf("服务器返回 %d: %s", resp.StatusCode, msg)
   191 │ 		}
   192 │ 	}
   193 │ 	if out != nil {
   194 │ 		return json.Unmarshal(data, out)
   195 │ 	}
   196 │ 	return nil
   197 │ }
