#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""查找录制输出：recordings 文件夹 与 .flv/.ts 录制文件（常见位置扫描）。"""
import os, glob, time

TARGETS = [
    r"C:\Users\Administrator\Downloads",
    r"C:\Users\Administrator\Desktop",
    r"C:\Users\Administrator\Documents",
    r"C:\Users\Administrator",
    r"D:\douyin-recorder-v3",
    r"D:\",
]

seen_dirs, seen_files = set(), []
for base in TARGETS:
    if not os.path.isdir(base):
        continue
    # 1) 找 recordings 目录（含 _fixed exe 可能被复制到的地方）
    for root, dirs, files in os.walk(base):
        # 跳过系统/隐藏/超大目录
        low = root.lower()
        if any(s in low for s in ("\\windows\\", "\\program files", "\\appdata\\", "\\node_modules", "\\.git\\", "\\tmp\\", "\\temp\\")):
            dirs[:] = [d for d in dirs if d.lower() not in ("appdata", "windows", "program files", "node_modules")]
            continue
        for d in dirs:
            if d.lower() == "recordings":
                seen_dirs.add(os.path.join(root, d))
        # 2) 找 flv/ts 文件（限制深度，避免扫整个 D 盘过慢）
        for f in files:
            if f.lower().endswith((".flv", ".ts")) and os.path.getsize(os.path.join(root, f)) > 1024:
                p = os.path.join(root, f)
                try:
                    mt = time.strftime("%Y-%m-%d %H:%M", time.localtime(os.path.getmtime(p)))
                except Exception:
                    mt = "?"
                seen_files.append((p, os.path.getsize(p), mt))
        # 控制递归深度：只对浅层继续
        if root.count(os.sep) - base.count(os.sep) > 5:
            dirs[:] = []

print("=== recordings 目录 ===")
for d in sorted(seen_dirs):
    print(" ", d)
if not seen_dirs:
    print("  (未找到名为 recordings 的目录)")

print("\n=== 录制文件 (.flv/.ts) ===")
for p, sz, mt in sorted(seen_files, key=lambda x: x[2], reverse=True)[:20]:
    print("  %8.1f KB  %s  %s" % (sz / 1024, mt, p))
if not seen_files:
    print("  (未找到 .flv/.ts 录制文件)")

